<script setup>
import { computed, ref } from 'vue'
import { weaponTypes, foundries, rarities } from '@/data/weapons'
import { gearItems, acquisitionById } from '@/data/v2'
import { useI18n, localized } from '@/i18n'
import { useManifestAssets } from '@/composables/useManifestAssets'

const { t } = useI18n()
const { weaponItems, status, iconFor, assetFor, plugSets, entityForHash, recordsForHash, vendorEntries, activityRewards } = useManifestAssets()

const keyword = ref('')
const slotFilter = ref('')
const familyFilter = ref('')
const rarityFilter = ref('')
const sortBy = ref('name')
const selectedWeapon = ref(null)

const slots = [
  { id: '', label: '全部槽位', en: 'All slots' },
  { id: 'kinetic', label: '动能槽', en: 'Kinetic' },
  { id: 'energy', label: '能量槽', en: 'Energy' },
  { id: 'power', label: '重型槽', en: 'Power' }
]
const officialSlotNames = { '': '全部槽位', kinetic: '动能槽', energy: '能量槽', power: '重型槽' }
const statLabels = { Impact: ['伤害', 'Impact'], Range: ['射程', 'Range'], Stability: ['稳定性', 'Stability'], Handling: ['操控性', 'Handling'], 'Reload Speed': ['填装速度', 'Reload Speed'], 'Aim Assistance': ['辅助瞄准', 'Aim Assistance'], Zoom: ['变焦', 'Zoom'], 'Recoil Direction': ['后坐方向', 'Recoil Direction'], Magazine: ['弹匣', 'Magazine'], 'Rounds Per Minute': ['射速', 'Rounds Per Minute'], Velocity: ['弹速', 'Velocity'], 'Blast Radius': ['爆炸范围', 'Blast Radius'], 'Charge Time': ['充能时间', 'Charge Time'], 'Draw Time': ['拉弓时间', 'Draw Time'], 'Airborne Effectiveness': ['空中效率', 'Airborne Effectiveness'] }

const familyOptions = computed(() => [...new Set(weaponItems.value.map(item => item.weaponFamily).filter(Boolean))].sort())
const rarityOptions = [
  { id: '', label: '全部稀有度', en: 'All rarities' },
  { id: 'exotic', label: '异域', en: 'Exotic' },
  { id: 'legendary', label: '传说', en: 'Legendary' },
  { id: 'other', label: '其他', en: 'Other' }
]
const query = computed(() => keyword.value.trim().toLowerCase())
const isExotic = item => item?.tierTypeHash === 2759499571
const isLegendary = item => item?.tierTypeHash === 4008398120
const matchesSlot = item => !slotFilter.value || item.ammoSlot === slotFilter.value
const matchesRarity = item => !rarityFilter.value || (rarityFilter.value === 'exotic' ? isExotic(item) : rarityFilter.value === 'legendary' ? isLegendary(item) : !isExotic(item) && !isLegendary(item))
const matchesQuery = item => !query.value || `${item.name} ${item.nameZh || ''} ${item.weaponFamily || ''} ${item.categoryNames?.join(' ') || ''} ${item.perkOptions?.join(' ') || ''} ${item.perkOptionsZh?.join(' ') || ''}`.toLowerCase().includes(query.value)
const officialCount = computed(() => weaponItems.value.filter(item => matchesSlot(item) && (!familyFilter.value || item.weaponFamily === familyFilter.value) && matchesRarity(item) && matchesQuery(item)).length)
const officialWeapons = computed(() => {
  const result = weaponItems.value.filter(item => matchesSlot(item) && (!familyFilter.value || item.weaponFamily === familyFilter.value) && matchesRarity(item) && matchesQuery(item))
  return result.sort((a, b) => sortBy.value === 'rarity' ? Number(isExotic(b)) - Number(isExotic(a)) || Number(isLegendary(b)) - Number(isLegendary(a)) || zhName(a).localeCompare(zhName(b), 'zh') : sortBy.value === 'family' ? (a.weaponFamily || '').localeCompare(b.weaponFamily || '') || zhName(a).localeCompare(zhName(b), 'zh') : zhName(a).localeCompare(zhName(b), 'zh')).slice(0, 120)
})
const displayedCount = computed(() => officialWeapons.value.length)
const canonicalExotics = computed(() => gearItems.filter(item => item.type === 'weapon' && item.rarity === 'exotic').filter(item => !query.value || `${item.name} ${item.en} ${(item.aliases || []).join(' ')}`.toLowerCase().includes(query.value)))
const filteredArchetypes = computed(() => weaponTypes.filter(w => (!slotFilter.value || (slotFilter.value === 'kinetic' ? w.slot.includes('动能') : slotFilter.value === 'energy' ? w.slot.includes('能量') : w.slot.includes('重型'))) && (!query.value || `${w.name} ${w.en} ${w.desc}`.toLowerCase().includes(query.value))))

function zhName(item) { return item?.nameZh || item?.name || item?.en || '未命名武器' }
function enName(item) { return item?.name || item?.en || item?.nameZh || 'Unnamed weapon' }
function icon(item) { const value = iconFor(item); return value || (item?.icon ? `https://www.bungie.net${item.icon}` : '') }
function slotLabel(item) { return officialSlotNames[item?.ammoSlot] || item?.ammoSlot || '槽位未登记' }
function rarityLabel(item) { return isExotic(item) ? '异域 / Exotic' : isLegendary(item) ? '传说 / Legendary' : '其他 / Other' }
function stats(item) { return Object.entries(item?.baseStats || {}).map(([key, value]) => ({ key, value, zh: statLabels[key]?.[0] || key, en: statLabels[key]?.[1] || key })).filter(stat => Number.isFinite(stat.value) && stat.value > 0 && !['Attack', 'Power'].includes(stat.key)).slice(0, 6) }
function pools(item) {
  return (item?.socketPools || []).filter(pool => /WEAPON PERK/i.test(pool.socketCategory || '')).map(pool => {
    const plugSet = plugSets.value.find(set => String(set.hash) === String(pool.plugSetHash))
    const entities = (plugSet?.plugItemHashes || []).map(hash => entityForHash(hash)).filter(Boolean)
    const zh = [...new Set([...(pool.plugNamesZh || []), ...entities.map(entity => entity.nameZh).filter(Boolean)])]
    const en = [...new Set([...(pool.plugNames || []), ...entities.map(entity => entity.name).filter(Boolean)])]
    return { ...pool, zh, en, count: Math.max(pool.plugItemCount || 0, zh.length, en.length) }
  }).filter(pool => pool.count || pool.zh.length || pool.en.length)
}
function sources(item) {
  const asset = assetFor(item) || item
  const vendors = recordsForHash(vendorEntries, asset.hash)
  const activities = recordsForHash(activityRewards, asset.hash)
  return [...(vendors.length ? vendors : asset.vendorSources || []).slice(0, 3).map(source => ({ kind: '商人 / Vendor', zh: source.vendorNameZh || '中文本地化未返回', en: source.vendorName || 'English name unavailable' })), ...(activities.length ? activities : asset.activitySources || []).slice(0, 3).map(source => ({ kind: '活动 / Activity', zh: source.activityNameZh || '中文本地化未返回', en: source.activityName || 'English name unavailable' }))]
}
function openDetail(item) { selectedWeapon.value = item }
function closeDetail() { selectedWeapon.value = null }
function resetFilters() { keyword.value = ''; slotFilter.value = ''; familyFilter.value = ''; rarityFilter.value = ''; sortBy.value = 'name' }
</script>

<template>
  <div class="weapons-page">
    <div class="page-head weapon-head"><div><p class="eyebrow">WEAPON ARCHIVE / MANIFEST ATLAS</p><h1>{{ t('pages.weapons.title') }}</h1><p>{{ t('pages.weapons.subtitle') }}</p></div><div class="catalog-stat"><strong>{{ weaponItems.length.toLocaleString() }}</strong><span>官方武器实体 / Manifest weapon entities</span></div></div>

    <section class="weapon-controls panel">
      <div class="control-main"><a-input v-model:value="keyword" size="large" allow-clear :placeholder="t('pages.weapons.search')" /><button class="reset-link" type="button" @click="resetFilters">重置筛选 / Reset</button></div>
      <div class="filter-row"><a-radio-group v-model:value="slotFilter" button-style="solid" class="filter-radio"><a-radio-button v-for="slot in slots" :key="slot.id" :value="slot.id">{{ slot.label }}<small>{{ slot.en }}</small></a-radio-button></a-radio-group><a-select v-model:value="familyFilter" allow-clear class="filter-select" placeholder="武器类型 / Weapon family"><a-select-option v-for="family in familyOptions" :key="family" :value="family">{{ family }}</a-select-option></a-select><a-select v-model:value="rarityFilter" class="filter-select" placeholder="稀有度 / Rarity"><a-select-option v-for="rarity in rarityOptions" :key="rarity.id" :value="rarity.id">{{ rarity.label }} / {{ rarity.en }}</a-select-option></a-select><a-select v-model:value="sortBy" class="filter-select" aria-label="排序"><a-select-option value="name">名称 / Name</a-select-option><a-select-option value="family">类型 / Family</a-select-option><a-select-option value="rarity">稀有度 / Rarity</a-select-option></a-select></div>
    </section>

    <section class="manifest-section"><div class="section-title"><div><h2>官方武器实体 / Official weapons</h2><p>每条记录均来自当前 Bungie Manifest 快照；点击卡片查看素体数值、Perk 池和获取来源。</p></div><span class="en">{{ officialCount.toLocaleString() }} MATCHES</span></div>
      <p v-if="status === 'loading'" class="empty">正在加载官方武器目录 / Loading Manifest weapons…</p><p v-else-if="status === 'error'" class="empty error">官方武器目录加载失败 / Failed to load the official catalog.</p>
      <template v-else><div class="result-line"><span>显示 {{ displayedCount }} / {{ officialCount.toLocaleString() }} 条</span><small>图标、名称、槽位、素体数值、Perk 池与来源均优先读取 Manifest</small></div><div class="official-grid"><button v-for="w in officialWeapons" :key="w.hash" type="button" class="official-weapon" :class="{ exotic: isExotic(w) }" @click="openDetail(w)"><div class="weapon-thumb"><img v-if="icon(w)" :src="icon(w)" :alt="`${zhName(w)} / ${enName(w)}`" loading="lazy" /><span v-else>无图标</span></div><div class="weapon-copy"><div class="official-top"><span class="badge" :class="{ gold: isExotic(w) }">{{ rarityLabel(w) }}</span><small>Hash {{ w.hash }}</small></div><h3>{{ zhName(w) }}</h3><p class="en-name">{{ enName(w) }}</p><p>{{ w.weaponFamily || '武器类型未登记' }} · {{ slotLabel(w) }}</p><div class="weapon-facts"><span v-if="w.socketCount">{{ w.socketCount }} 插槽 / sockets</span><span v-if="pools(w).length">{{ pools(w).reduce((sum, pool) => sum + pool.count, 0) }} 个 Perk 选项 / perk options</span></div></div></button></div><p v-if="!officialWeapons.length" class="empty">没有匹配的官方武器实体 / No matching Manifest weapons.</p><p v-else-if="officialCount > displayedCount" class="catalog-note">当前展示前 {{ displayedCount }} 条。继续缩小筛选范围可定位具体武器。</p></template>
    </section>

    <section class="knowledge-section"><div class="section-title"><div><h2>{{ t('pages.weapons.archetypes') }} / Archetypes</h2><p>这里解释武器原型在战斗中的定位，不代替具体武器的 Manifest 数据。</p></div><span class="en">FIELD GUIDE</span></div><div class="grid grid-3"><article v-for="w in filteredArchetypes" :key="w.id" class="card archetype-card"><div class="w-top"><span class="badge gold">{{ w.slot }}</span><span class="range">{{ w.range }}距离 / range</span></div><h3>{{ localized(w) }}</h3><span class="en-tag">{{ w.en.toUpperCase() }}</span><p>{{ w.desc }}</p></article></div><div v-if="!filteredArchetypes.length" class="empty">没有匹配的武器原型。</div></section>

    <section class="knowledge-section"><div class="section-title"><div><h2>{{ t('pages.weapons.exotics') }} / Featured exotics</h2><p>精选构筑中的异域武器入口；完整实体、素体和 Perk 信息以官方武器列表为准。</p></div><span class="en">CURATED INDEX</span></div><div class="grid grid-3"><article v-for="w in canonicalExotics" :key="w.id" class="card exotic-card"><div class="exo-top"><span class="badge gold">异域 / EXOTIC</span><span class="wtype">{{ w.type }}</span></div><h3>✦ {{ localized(w) }}</h3><span class="en-tag">{{ w.en.toUpperCase() }}</span><p>{{ w.description || '官方装备定义已接入；点击上方 Manifest 条目查看可核验数据。' }}</p><div class="how">槽位：{{ w.slot }} / {{ w.en }}；获取路径：{{ acquisitionById[w.acquisitionId]?.name || '待核验 / pending verification' }}</div></article></div><div v-if="!canonicalExotics.length" class="empty">没有匹配的精选异域武器。</div></section>

    <section class="reference-grid"><div class="panel info-panels"><h3>稀有度 / Rarity</h3><table><thead><tr><th>等级 / Tier</th><th>说明 / Meaning</th></tr></thead><tbody><tr v-for="r in rarities" :key="r.level"><td><span class="badge" :class="{ gold: r.level === 'exotic' }">{{ r.name }} / {{ r.level }}</span></td><td>{{ r.cn }}</td></tr></tbody></table></div><div class="panel info-panels"><h3>制造商 / Foundries</h3><div class="foundry-list"><div v-for="f in foundries" :key="f.name" class="foundry"><span class="f-name">{{ f.name }}</span><span class="f-style">{{ f.style }}</span></div></div></div></section>

    <div v-if="selectedWeapon" class="weapon-overlay" @click.self="closeDetail"><section class="weapon-dialog" role="dialog" aria-modal="true" :aria-label="`${zhName(selectedWeapon)} weapon details`"><button type="button" class="detail-close" aria-label="关闭详情" @click="closeDetail">×</button><header class="weapon-detail-head"><div class="detail-weapon-icon"><img v-if="icon(selectedWeapon)" :src="icon(selectedWeapon)" :alt="`${zhName(selectedWeapon)} / ${enName(selectedWeapon)}`" /></div><div><span class="badge" :class="{ gold: isExotic(selectedWeapon) }">{{ rarityLabel(selectedWeapon) }}</span><h2>{{ zhName(selectedWeapon) }}</h2><p>{{ enName(selectedWeapon) }}</p><small>Hash {{ selectedWeapon.hash }} · {{ selectedWeapon.weaponFamily || 'Weapon family unavailable' }} · {{ slotLabel(selectedWeapon) }}</small></div></header><section v-if="selectedWeapon.descriptionZh || selectedWeapon.description" class="detail-block"><h3>武器说明 / Description</h3><p v-if="selectedWeapon.descriptionZh"><b>中文</b> {{ selectedWeapon.descriptionZh }}</p><p v-if="selectedWeapon.description"><b>English</b> {{ selectedWeapon.description }}</p></section><section v-if="stats(selectedWeapon).length" class="detail-block"><h3>武器素体数值 / Base stats</h3><div class="stat-grid"><div v-for="stat in stats(selectedWeapon)" :key="stat.key" class="stat-item"><span>{{ stat.zh }} <small>{{ stat.en }}</small></span><strong>{{ stat.value }}</strong><i><b :style="{ width: `${Math.min(100, Number(stat.value))}%` }"></b></i></div></div></section><section class="detail-block"><h3>Perk 池 / Perk pools</h3><div v-if="pools(selectedWeapon).length" class="pool-list"><article v-for="(pool, index) in pools(selectedWeapon)" :key="`${pool.socketTypeHash}-${index}`"><strong>第 {{ index + 1 }} 列 / Column {{ index + 1 }} · {{ pool.count }} options</strong><p v-if="pool.zh.length"><b>中文</b> {{ pool.zh.join('、') }}</p><p v-if="pool.en.length"><b>English</b> {{ pool.en.join(', ') }}</p><p v-if="!pool.zh.length && !pool.en.length" class="muted">仅返回 PlugSet 哈希，当前本地化快照没有名称。</p></article></div><p v-else class="muted">该实体没有可展开的武器 Perk 池记录，或 Manifest 仅返回基础插槽。</p></section><section v-if="sources(selectedWeapon).length" class="detail-block"><h3>获取来源 / Acquisition</h3><div class="source-list"><article v-for="(source, index) in sources(selectedWeapon)" :key="`${source.kind}-${index}`"><span>{{ source.kind }}</span><strong>{{ source.zh }}</strong><small>{{ source.en }}</small></article></div></section><footer>数据来源：Bungie Manifest 快照 · 点击右上角或空白处关闭</footer></section></div>
  </div>
</template>

<style scoped>
.weapons-page{padding-bottom:4rem}.weapon-head{display:flex;justify-content:space-between;gap:2rem;align-items:end}.eyebrow{color:var(--gold-dim);font:.66rem var(--font-en);letter-spacing:.18em}.catalog-stat{min-width:15rem;padding:1rem 1.2rem;border-left:2px solid var(--gold);background:rgba(255,255,255,.035)}.catalog-stat strong{display:block;color:var(--gold-bright);font:700 1.45rem var(--font-en);font-variant-numeric:tabular-nums}.catalog-stat span{color:var(--text-dim);font-size:.65rem}.weapon-controls{display:grid;gap:1rem;margin:1.2rem 0 2rem;padding:1rem}.control-main{display:flex;gap:.8rem;align-items:center}.control-main .ant-input-affix-wrapper{flex:1}.reset-link{border:0;background:none;color:var(--gold-dim);font-size:.65rem;cursor:pointer;white-space:nowrap}.filter-row{display:flex;gap:.55rem;flex-wrap:wrap;align-items:center}.filter-radio{display:flex;gap:.35rem;flex-wrap:wrap}.filter-radio .ant-radio-button-wrapper{height:auto;min-height:2.35rem;padding:.4rem .65rem;border:1px solid var(--line-soft);background:transparent;color:var(--text-sub);line-height:1.15}.filter-radio .ant-radio-button-wrapper::before{display:none}.filter-radio .ant-radio-button-wrapper small{display:block;color:var(--text-dim);font-size:.53rem;margin-top:.14rem}.filter-radio .ant-radio-button-wrapper-checked{border-color:var(--gold);background:rgba(232,193,90,.1);color:var(--gold-bright)}.filter-select{min-width:10rem}.section-title{display:flex;justify-content:space-between;align-items:end;gap:1rem;margin:2rem 0 .8rem}.section-title h2{margin:0;font-size:1rem}.section-title p{margin:.25rem 0 0;color:var(--text-dim);font-size:.68rem;max-width:44rem}.section-title>.en{color:var(--gold-dim);font:.6rem var(--font-en);white-space:nowrap}.result-line{display:flex;justify-content:space-between;gap:1rem;align-items:baseline;margin:-.25rem 0 .7rem;color:var(--gold-bright);font:.7rem var(--font-en)}.result-line small{color:var(--text-dim);font:400 .64rem var(--font-cn)}.official-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line-soft);max-height:62rem;overflow:auto}.official-weapon{display:grid;grid-template-columns:4.2rem 1fr;gap:.7rem;min-width:0;padding:.75rem;background:var(--bg-dark);border:0;color:inherit;text-align:left;cursor:pointer;transition:background .2s,transform .2s}.official-weapon:hover{background:rgba(232,193,90,.08);transform:translateY(-1px)}.official-weapon:focus-visible{outline:2px solid var(--gold-bright);outline-offset:-2px}.official-weapon.exotic{background:linear-gradient(120deg,rgba(232,193,90,.1),var(--bg-dark) 60%)}.weapon-thumb{width:4.2rem;height:4.2rem;display:flex;align-items:center;justify-content:center;background:#121212;border:1px solid var(--line-soft);overflow:hidden}.weapon-thumb img{width:100%;height:100%;object-fit:contain}.weapon-thumb span{color:var(--text-dim);font-size:.56rem}.weapon-copy{min-width:0}.official-top{display:flex;justify-content:space-between;gap:.4rem;align-items:center}.official-top small{color:var(--text-dim);font:.52rem var(--font-en);white-space:nowrap}.badge{display:inline-block;color:var(--text-dim);font-size:.54rem;letter-spacing:.04em}.badge.gold{color:var(--gold-bright)}.official-weapon h3{margin:.25rem 0 .08rem;font-size:.8rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.en-name{font:.56rem var(--font-en)!important;color:var(--gold-dim)!important;margin:0 0 .2rem!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.official-weapon p{font-size:.62rem;color:var(--text-sub);margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.weapon-facts{display:flex;gap:.55rem;flex-wrap:wrap;margin-top:.35rem;color:var(--text-dim);font-size:.54rem}.catalog-note,.muted{color:var(--text-dim);font-size:.64rem}.empty{text-align:center;padding:3rem;color:var(--text-dim)}.error{color:var(--warn)}.knowledge-section{margin-top:2.3rem}.archetype-card{min-height:10rem}.en-tag{display:block;font:.58rem var(--font-en);letter-spaci